/* بيانات باب amal: تُحمَّل عند أول فتح للقسم */
window.AMAL = {"ch":[{"id":"sa3y","t":"منزلة السعي والكسب","d":"الآيات التي جعلت السعي في الأرض وابتغاء الفضل والكسب الحلال من مقتضيات العمران، وربطت ما يناله الإنسان بما سعى."},{"id":"itqan","t":"الإتقان والإحسان والكفاءة","d":"الآيات التي تصف العمل المطلوب بالإحسان والإتقان، والأجير القوي الأمين، والحفظ والعلم في تولّي المسؤولية."},{"id":"amana","t":"الأمانة والعدل والحلال في الكسب","d":"الآيات التي تضبط الكسب بالوفاء في الكيل والوزن وأداء الأمانة وطيب المطعم ووفاء الأجرة وصون النفس."},{"id":"qasas","t":"قصص العمل في القرآن","d":"ما قصّه القرآن من أعمال الأنبياء والصالحين وصنائعهم: السقي والرعي والحدادة وصناعة السفينة وبناء السد والتخطيط للزراعة."},{"id":"kasal","t":"الكسل والتواكل والغفلة والإسراف","d":"الآيات التي تعالج التثاقل وطول الفراغ والتواكل وسوء التدبير والاغترار بالمال والانشغال به عن الذكر."},{"id":"ajr","t":"جزاء العامل","d":"الآيات التي تخبر أن عمل العامل لا يضيع ولو كان مثقال ذرة، وما وعد الله به من الحياة الطيبة والأجر."}],"tp":[{"id":"saay","ch":"sa3y","t":"ليس للإنسان إلا ما سعى","e":"ما يناله الإنسان من سعيه وأن سعيه سوف يُرى ثم يُجزى به.","ay":[[53,39,41]],"q":[{"bk":"saadi","s":53,"ay":39,"x":"{وأن ليس للإنسان إلاَّ ما سَعى}؛ أي: كلُّ عامل له عمله الحسن والسيئُ؛ فليس له من عمل غيره وسعيه شيء، ولا يتحمَّل أحدٌ عن أحدٍ ذنباً، {وأنَّ سعيَه سوف يُرى}: في الآخرة، فيميَّز حسنُه من سيِّئه، {ثم يُجۡزاه الجزاءَ الأوفى}؛ أي: المستكمل لجميع العمل، الخالص الحسن بالحسنى، والسيئ الخالص بالسوأى، والمشوب بحسبه؛ جزاء تُقِرُّ بعدله وإحسانه الخليقة كلها، وتَحْمَدُ الله عليه، حتى إنَّ أهل النار ليدخلون النار، وإنَّ قلوبهم مملوءةٌ من حمد ربِّهم والإقرار له بكمال الحكمة ومقت أنفسهم، وأنَّهم الذين أوصلوا أنفسهم وأوردوها شرَّ الموارد.","w":"السعدي","en":"Al-Sa'di: every worker has his own good or bad work and nothing of another's work or striving; no one bears another's sin; his striving will be seen in the Hereafter and he will be repaid with the fullest repayment, good with good and evil with evil, in a way that all creation acknowledges as just."}]},{"id":"amal105","ch":"sa3y","t":"«اعملوا فسيرى الله عملكم»","e":"الأمر بالعمل ومعنى أن الله ورسوله والمؤمنين يرون العمل.","ay":[[9,105,105]],"q":[{"bk":"ibnkathir","s":9,"ay":105,"x":"وَقَالَ الْبُخَارِيُّ: قَالَتْ عَائِشَةُ، رَضِيَ اللَّهُ عَنْهَا: إِذَا أَعْجَبَكَ حُسن عَمَلِ امْرِئٍ، فَقُلْ: ﴿اعْمَلُوا فَسَيَرَى اللَّهُ عَمَلَكُمْ وَرَسُولُهُ وَالْمُؤْمِنُونَ﴾ .","w":"ابن كثير","en":"Ibn Kathir: al-Bukhari reported that A'isha said: if someone's good work impresses you, say: 'Work, for Allah will see your work, and His Messenger and the believers.'"},{"bk":"saadi","s":9,"ay":105,"x":"ويُحتمل أنَّ المعنى: إنَّكم مهما عملتُم من خيرٍ أو شرٍّ؛ فإنَّ الله مطَّلعٌ عليكم، وسَيُطْلِعُ رسولَه وعباده المؤمنين على أعمالكم ولو كانت باطنةً.","w":"السعدي","en":"Al-Sa'di: the verse can also mean that whatever you do of good or evil, Allah is aware of you and will show His Messenger and the believers your deeds, even those that are hidden."}]},{"id":"mashy","ch":"sa3y","t":"المشي في مناكب الأرض والأكل من رزق الله","e":"تذليل الأرض والأمر بالمشي في أطرافها والأكل من الرزق.","ay":[[67,15,15]],"q":[{"bk":"saadi","s":67,"ay":15,"x":"أي: هو الذي سخَّر لكم الأرضَ وذَلَّلها؛ لتدرِكوا منها كلَّ ما تعلقت به حاجتُكم من غرسٍ وبناءٍ وحرثٍ وطرقٍ يُتَوَصَّلُ بها إلى الأقطار النائية والبلدان الشاسعة، {فامشوا في مناكِبِها}؛ أي: لطلب الرزق والمكاسب، {وكُلوا من رزقِهِ وإليه النشورُ}؛ أي: بعد أن تنتقلوا من هذه الدار التي جَعَلَها الله امتحاناً وبلغةً يُتَبَلَّغُ بها إلى الدار الآخرة؛ تُبعثون بعد موتكم وتُحشرون إلى الله؛ ليجازِيَكم بأعمالكم الحسنة والسيئة.","w":"السعدي","en":"Al-Sa'di: Allah subdued the earth so that people can get from it all they need of planting, building, farming and roads that reach distant lands; 'so walk in its regions' means to seek provision and earnings, 'and eat of His provision', and then to Him is the resurrection, when each is repaid for his deeds."}]},{"id":"intishar","ch":"sa3y","t":"الانتشار في الأرض بعد الصلاة وابتغاء الفضل","e":"الإذن بالانتشار والابتغاء بعد انقضاء الصلاة، مع ذكر الله.","ay":[[62,9,10]],"q":[{"bk":"saadi","s":62,"ay":10,"x":"وهذا الأمر بترك البيع موقَّت مدَّة الصلاة؛ {فإذا قُضِيَتِ الصلاةُ فانتشروا في الأرض}: لطلب المكاسب والتجارات، ولما كان الاشتغال بالتجارة مَظِنَّةُ الغفلة عن ذكر الله؛ أمر الله بالإكثار من ذكره؛ لينجبر بهذا، فقال:{واذكروا الله كثيراً}؛ أي: في حال قيامكم وقعودكم وعلى جنوبكم، {لعلَّكم تفلحون}: فإنَّ الإكثار من ذِكْر الله أكبر أسباب الفلاح.","w":"السعدي","en":"Al-Sa'di: the ban on selling lasts only for the prayer; 'when the prayer is finished, disperse in the land' to seek earnings and trade; since trade can lead to heedlessness, Allah ordered much remembrance of Him so that this makes up for it, for much remembrance is the greatest cause of success."},{"bk":"ibnkathir","s":62,"ay":10,"x":"وَقَوْلُهُ: ﴿فَإِذَا قُضِيَتِ الصَّلاةُ﴾ أَيْ: فُرغ مِنْهَا، ﴿فَانْتَشِرُوا فِي الأرْضِ وَابْتَغُوا مِنْ فَضْلِ اللَّهِ﴾ لَمَّا حَجَر عَلَيْهِمْ فِي التَّصَرُّفِ بَعْدَ النِّدَاءِ وَأَمَرَهُمْ بِالِاجْتِمَاعِ، أَذِنَ لَهُمْ بَعْدَ الْفَرَاغِ فِي الِانْتِشَارِ فِي الْأَرْضِ وَالِابْتِغَاءِ مِنْ فَضْلِ اللَّهِ.","w":"ابن كثير","en":"Ibn Kathir: when Allah restricted their dealings after the call and ordered them to gather, He permitted them after it was over to disperse in the land and seek of Allah's bounty."}]},{"id":"ibtigha","ch":"sa3y","t":"ابتغاء فضل الله بالتجارة والضرب في الأرض","e":"ابتغاء الفضل بالتجارة في المواسم وفي السفر.","ay":[[2,198,198],[73,20,20]],"q":[{"bk":"saadi","s":2,"ay":198,"x":"لما أمر تعالى بالتقوى أخبر تعالى أن ابتغاء فضل الله بالتكسب في مواسم الحج وغيره ليس فيه حرج إذا لم يشغل عما يحب إذا كان المقصود هو الحج، وكان الكسب حلالاً منسوباً إلى فضل الله؛ لا منسوباً إلى حذق العبد والوقوف مع السبب ونسيان المسبب، فإن هذا هو الحرج بعينه …","w":"السعدي","en":"Al-Sa'di: seeking Allah's bounty by earning during the Hajj season and at other times is no sin, provided it does not distract from what is obligatory, Hajj is the aim, and the earning is lawful and attributed to Allah's bounty, not to the person's own cleverness while he stops at the means and forgets the One who gives them; that is the real sin."},{"bk":"qurtubi","s":73,"ay":20,"x":"الثَّامِنَةُ- سَوَّى اللَّهُ تَعَالَى فِي هَذِهِ الْآيَةِ بَيْنَ دَرَجَةِ الْمُجَاهِدِينَ وَالْمُكْتَسِبِينَ الْمَالَ الْحَلَالَ لِلنَّفَقَةِ عَلَى نَفْسِهِ وَعِيَالِهِ، وَالْإِحْسَانِ وَالْإِفْضَالِ، فَكَانَ هَذَا دَلِيلًا عَلَى أَنَّ كَسْبَ الْمَالِ بِمَنْزِلَةِ الْجِهَادِ، لِأَنَّهُ جَمَعَهُ مَعَ الْجِهَادِ فِي سَبِيلِ اللَّهِ.","w":"القرطبي","en":"Al-Qurtubi: in this verse Allah placed on one level the mujahidin and those who earn lawful money to spend on themselves and their families and to do good and give generously, which shows that earning money has the rank of jihad since He joined it with jihad in His cause."}]},{"id":"maash","ch":"sa3y","t":"جعل الأرض معاشاً: الحرث والحرف والمكاسب","e":"ما جعل الله في الأرض من وجوه المعاش: الحرث والماشية والحرف والتجارات.","ay":[[7,10,10],[15,19,20]],"q":[{"bk":"saadi","s":15,"ay":20,"x":"{وجعلنا لكم فيها معايش}: من الحرث ومن الماشية ومن أنواع المَكاسب والحِرَف، {ومَنۡ لستم له برازقين}؛ أي: أنعمنا عليكم بعبيدٍ وإماءٍ وأنعامٍ لنفعكم ومصالحكم، وليس عليكم رزقُها، بل خوَّلكم الله إيَّاها، وتكفَّل بأرزاقها.","w":"السعدي","en":"Al-Sa'di: 'We made for you in it livelihoods': from farming, from livestock and from all kinds of earnings and crafts."},{"bk":"saadi","s":7,"ay":10,"x":"يقول تعالى ممتنًّا على عباده بذكر المسكن والمعيشة: {ولقد مكَّنَّاكم في الأرض}؛ أي: هيأناها لكم بحيث تتمكَّنون من البناء عليها وحرثها ووجوه الانتفاع بها، {وجَعَلۡنا لكم فيها معايشَ}: مما يخرج من الأشجار والنبات ومعادن الأرض وأنواع الصنائع والتجارات؛ فإنه هو الذي هيَّأها وسخَّر أسبابها، {قليلاً ما تشكُرون}: الله الذي أنعم عليكم بأصناف النعم، وصَرَفَ عنكم النقم.","w":"السعدي","en":"Al-Sa'di: Allah reminds His servants of His favour of homes and livelihood: He established them in the earth so they can build on it, farm it and benefit from it in many ways; and He gave them livelihoods from trees, plants, the earth's minerals and all kinds of crafts and trade, for He is the One who prepared them and made their means available; yet little do they give thanks."}]},{"id":"kasb","ch":"sa3y","t":"نصيب كل عامل مما اكتسب","e":"نصيب الرجال والنساء مما اكتسبوا، والإنفاق من طيبات الكسب.","ay":[[4,32,32],[2,267,267]],"q":[{"bk":"saadi","s":4,"ay":32,"x":"فكل منهم لا يناله غير ما كسبه وتعب فيه. {واسألوا الله من فضله}؛ أي: من جميع مصالحكم في الدين والدنيا؛ فهذا كمال العبد وعنوانُ سعادته، لا من يترك العمل أو يتَّكِلُ على نفسه غير مفتقرٍ لربِّه أو يجمع بين الأمرين؛ فإنَّ هذا مخذولٌ خاسرٌ.","w":"السعدي","en":"Al-Sa'di: each of them gets only what he earned and toiled for; 'ask Allah of His bounty' for all your interests in religion and this world; this is the completeness of the servant, not that of one who abandons work or relies on himself without needing his Lord, or mixes the two, for such a one is forsaken and a loser."},{"bk":"ibnkathir","s":2,"ay":267,"x":"وَقَالَ عَلِيٌّ وَالسُّدِّيُّ: ﴿مِنْ طَيِّبَاتِ مَا كَسَبْتُم﴾ يَعْنِي: الذَّهَبُ وَالْفِضَّةُ، وَمِنَ الثِّمَارِ وَالزُّرُوعِ الَّتِي أَنْبَتَهَا لَهُمْ مِنَ الْأَرْضِ.","w":"ابن كثير","en":"Ibn Kathir: Ali and al-Suddi said that 'of the good of what you earned' means gold and silver, and the fruits and crops that Allah caused the earth to grow for them."}]},{"id":"ahsan","ch":"itqan","t":"أحسن عملاً: الإخلاص والصواب","e":"الابتلاء بأحسن العمل، ومعنى إحسان العمل.","ay":[[67,2,2],[18,30,30]],"q":[{"bk":"saadi","s":67,"ay":2,"x":"و {خَلَقَ الموتَ والحياةَ}؛ أي: قدَّر لعباده أن يُحْييَهم ثم يُميتهم؛ {لِيَبۡلُوَكم أيُّكم أحسنُ عملاً}؛ أي: أخلصه وأصوبه، وذلك أنَّ الله خلق عباده وأخرجهم لهذه الدار، وأخبرهم أنَّهم سيُنقلون منها، وأمرهم ونهاهم، وابتلاهم بالشهوات المعارضة لأمره؛ فمن انقاد لأمر الله وأحسن العمل؛ أحسن الله له الجزاء في الدارين، ومن مال مع شهوات النفس ونبذ أمر الله؛ فله شرُّ الجزاء.","w":"السعدي","en":"Al-Sa'di: Allah created death and life to test you as to which of you is best in deed, meaning the most sincere and most correct; whoever submits to Allah's command and does well, Allah rewards him well in both worlds, and whoever follows his desires and casts the command aside has the worst reward."},{"bk":"saadi","s":18,"ay":30,"x":"وإحسانُ العمل أن يريدَ العبدُ العمل لوجه الله متبعاً في ذلك شرع الله؛ فهذا العمل لا يضيِّعه الله ولا شيئاً منه، بل يحفظُه للعاملين، ويوفِّيهم من الأجر بحسب عملهم وفضله وإحسانه.","w":"السعدي","en":"Al-Sa'di: doing a deed well means that the servant intends the deed for Allah's sake while following Allah's law; such a deed Allah does not lose, not even a part of it; He keeps it for the workers and repays them according to their work, His favour and His goodness."}]},{"id":"itqan","ch":"itqan","t":"صنع الله الذي أتقن كل شيء","e":"وصف الله صنعه بالإتقان، ومعنى الإتقان.","ay":[[27,88,88]],"q":[{"bk":"qurtubi","s":27,"ay":88,"x":"\"الَّذِي أَتْقَنَ كُلَّ شَيْءٍ\" أَيْ أَحْكَمَهُ، وَمِنْهُ قَوْلُ النَّبِيِّ ﷺ: \"رَحِمَ اللَّهُ مَنْ عَمِلَ عَمَلًا فأتقنه\".","w":"القرطبي","en":"Al-Qurtubi: 'who perfected everything' means He made it firm and exact, and from this comes the Prophet's saying (peace be upon him): 'May Allah have mercy on one who does a work and does it well.'"}]},{"id":"qawi","ch":"itqan","t":"«إن خير من استأجرت القوي الأمين»","e":"اجتماع القوة والأمانة في الأجير واعتبارهما فيمن يتولى عملاً.","ay":[[28,26,26]],"q":[{"bk":"saadi","s":28,"ay":26,"x":"{قالتۡ إحداهُما}؛ أي: إحدى ابنتيهِ: {يا أبتِ اسۡتَأجِرۡه}؛ أي: اجْعَلْه أجيراً عندك يرعى الغنم ويسقيها، {إنَّ خير مَنِ استأجرتَ القويُّ الأمينُ}؛ أي: إنَّ موسى أولى مَنِ استُؤْجِرَ؛ فإنَّه جمع القوَّة والأمانة، وخير أجيرٍ استُؤْجِرَ مَن جَمَعَهما؛ [أي]: القوَّة والقدرة على ما استُؤْجِرَ عليه، والأمانة فيه بعدم الخيانة، وهذان الوصفان ينبغي اعتبارُهما في كلِّ مَنْ يَتَوَلَّى للإنسان عملاً بإجارة أو غيرها؛ فإنَّ الخلل لا يكون إلا بفقدِهِما أو فقد إحداهما، وأمَّا اجتماعُهما؛ فإنَّ العمل يتمُّ ويكمُلُ.","w":"السعدي","en":"Al-Sa'di: one of the two daughters said 'Father, hire him; the best to hire is the strong, the trustworthy', meaning Musa was the most fitting to be hired because he combined strength and trustworthiness; these two qualities should be considered in anyone who takes on work for a person, by hire or otherwise, since defect appears only when both or one is missing, and when both are present the work is completed and perfected."},{"bk":"ibnkathir","s":28,"ay":26,"x":"قَالَ سُفْيَانُ الثَّوْرِيُّ، عَنْ أَبِي إِسْحَاقَ، عَنْ أَبِي عُبَيْدَةَ، عَنْ عَبْدِ اللَّهِ -هُوَ ابْنُ مَسْعُودٍ -قَالَ: أَفَرَسُ النَّاسِ ثَلَاثَةٌ: أَبُو بَكْرٍ حِينَ تَفَرَّسَ فِي عُمَر، وَصَاحِبُ يُوسُفَ حِينَ قَالَ: ﴿أَكْرِمِي مَثْوَاهُ﴾ [يُوسُفَ: ٢١] ، وَصَاحِبَةُ مُوسَى حِينَ قَالَتْ: ﴿يَا أَبَتِ اسْتَأْجِرْهُ إِنَّ خَيْرَ مَنِ اسْتَأْجَرْتَ الْقَوِيُّ الأمِينُ﴾ .","w":"ابن كثير","en":"Ibn Kathir: Sufyan al-Thawri reported from Ibn Mas'ud: the three most perceptive people were Abu Bakr when he judged Umar, the man who bought Yusuf when he said 'give him an honourable stay', and Musa's wife when she said 'Father, hire him; the best to hire is the strong, the trustworthy'."}]},{"id":"hafiz","ch":"itqan","t":"«إني حفيظ عليم»: الكفاءة والأمانة في المسؤولية","e":"طلب يوسف عليه السلام ولاية خزائن الأرض ووصفه نفسه بالحفظ والعلم.","ay":[[12,54,55]],"q":[{"bk":"saadi","s":12,"ay":55,"x":"أي: حفيظ للَّذي أتولاَّه؛ فلا يضيعُ منه شيءٌ في غير محلِّه، وضابطٌ للداخل والخارج، عليمٌ بكيفيَّة التدبير والإعطاء والمنع والتصرُّف في جميع أنواع التصرُّفات.","w":"السعدي","en":"Al-Sa'di: 'I am a knowing guardian' means he is a guardian of what he takes charge of so nothing is lost or put in the wrong place, he keeps account of what comes in and goes out, and knows how to manage, give, withhold and handle every kind of affair."},{"bk":"ibnkathir","s":12,"ay":55,"x":"فَقَالَ يُوسُفُ، عَلَيْهِ السَّلَامُ: ﴿اجْعَلْنِي عَلَى خَزَائِنِ الأرْضِ إِنِّي حَفِيظٌ عَلِيمٌ﴾ مَدَحَ نَفْسَهُ، وَيَجُوزُ لِلرَّجُلِ ذَلِكَ إِذَا جُهِل أَمْرُهُ، لِلْحَاجَةِ","w":"ابن كثير","en":"Ibn Kathir: Yusuf said 'Appoint me over the storehouses of the land; I am a knowing guardian'; he praised himself, and a man may do so when his worth is unknown and there is a need."}]},{"id":"amana","ch":"itqan","t":"أداء الأمانات ورعايتها","e":"الأمر بأداء الأمانات إلى أهلها ووصف المؤمنين برعايتها.","ay":[[4,58,58],[23,8,8]],"q":[{"bk":"saadi","s":4,"ay":58,"x":"الأمانات كلُّ ما اؤتُمِنَ عليه الإنسان وأُمِرَ بالقيام به، فأمر اللهُ عباده بأدائِها؛ أي: كاملة موفَّرة لا منقوصة ولا مبخوسةً ولا ممطولاً بها، ويدخُلُ في ذلك أماناتُ الولايات والأموال والأسرار والمأمورات التي لا يطَّلع عليها إلا الله.","w":"السعدي","en":"Al-Sa'di: trusts are everything a person has been trusted with and ordered to carry out; Allah ordered His servants to discharge them complete, in full, not reduced, not withheld, not delayed; this includes trusts of office, of wealth, of secrets and of duties that only Allah knows about."},{"bk":"saadi","s":23,"ay":8,"x":"{والذين هم لأماناتِهِم وعَهۡدِهِم راعونَ}؛ أي: مراعون لها، ضابطون، حافظون، حريصون على القيام بها وتنفيذها.","w":"السعدي","en":"Al-Sa'di: 'those who are keepers of their trusts and their covenant' means they watch over them, take care of them, keep them and are eager to fulfil and carry them out."}]},{"id":"tatfif","ch":"amana","t":"التطفيف في الكيل والوزن","e":"الوعيد على الذين يستوفون إذا اكتالوا ويخسرون إذا كالوا.","ay":[[83,1,6]],"q":[{"bk":"saadi","s":83,"ay":1,"x":"وإذا كان هذا وعيداً على الذين يَبْخَسونَ الناس بالمكيال والميزان؛ فالذي يأخذ أموالهم قهراً وسرقةً أولى بهذا الوعيد من المطفِّفين.","w":"السعدي","en":"Al-Sa'di: if this is a warning to those who cheat people in measure and weight, then one who takes their wealth by force or theft deserves the warning even more than the cheaters."},{"bk":"qurtubi","s":83,"ay":1,"x":"وَقَالَ نَافِعٌ: كَانَ ابْنُ عُمَرَ يَمُرُّ بِالْبَائِعِ فَيَقُولُ: أتق الله وأوف الكيل وَالْوَزْنَ بِالْقِسْطِ، فَإِنَّ الْمُطَفِّفِينَ يَوْمَ الْقِيَامَةِ يُوقَفُونَ حَتَّى إِنَّ الْعَرَقَ لَيُلْجِمُهُمْ إِلَى أَنْصَافِ آذَانِهِمْ.","w":"القرطبي","en":"Al-Qurtubi: Nafi' said that Ibn Umar would pass a seller and say: 'Fear Allah and give full measure and weight with justice, for on the Day of Resurrection the cheaters will be made to stand until their sweat reaches halfway up their ears.'"}]},{"id":"shuayb","ch":"amana","t":"شعيب وإيفاء المكيال والميزان","e":"دعوة شعيب قومه إلى إيفاء الكيل والميزان وترك البخس.","ay":[[11,84,85],[26,181,183]],"q":[{"bk":"saadi","s":11,"ay":84,"x":"ومنها: أن نقصَ المكاييل والموازين من كبائر الذُّنوب وتخشى العقوبة العاجلة على من تعاطى ذلك، وأنَّ ذلك من سرقة أموال الناس، وإذا كان سرقتهم في المكاييل والموازين موجبةً للوعيد؛ فسرِقَتُهم على وجه القهر والغلبة من باب أولى وأحرى.","w":"السعدي","en":"Al-Sa'di: among the lessons is that cheating in measures and weights is a major sin, that swift punishment is feared for whoever does it, that it is a theft of people's wealth, and that if this theft earns a warning, then taking it by force and domination deserves it all the more."},{"bk":"saadi","s":11,"ay":84,"x":"ومنها: أنَّ المال الذي يرزقُهُ الله الإنسان، وإنْ كان الله قد خوَّله إياه؛ فليس له أن يصنع فيه ما يشاء؛ فإنه أمانةٌ عنده، عليه أن يقيم حقَّ الله فيه بأداء ما فيه من الحقوق والامتناع من المكاسب التي حرَّمها الله ورسوله، لا كما يزعمه الكفار ومن أشبههم؛ أنَّ أموالهم لهم أن يصنعوا فيها ما يشاؤون ويختارون، سواءٌ وافقَ حكمَ الله أو خالفه.","w":"السعدي","en":"Al-Sa'di: the wealth Allah gives a person, though He has entrusted it to him, is not his to do with as he pleases; it is a trust in his hands, and he must give Allah's due from it and avoid the earnings Allah and His Messenger forbade, unlike what the disbelievers claim, that their wealth is theirs to use as they like whether or not it agrees with Allah's ruling."},{"bk":"saadi","s":11,"ay":84,"x":"ومنها: أن على العبد أن يَقْنَعَ بما آتاه الله ويَقْنَعَ بالحلال عن الحرام وبالمكاسب المباحة عن المكاسب المحرمة، وأنَّ ذلك خيرٌ له؛ لقوله:{بقيَّةُ الله خيرٌ لكم}؛ ففي ذلك من البركة وزيادة الرزق ما ليس في التكالب على الأسباب المحرَّمة من المَحْق وضدِّ البركة.","w":"السعدي","en":"Al-Sa'di: the servant should be content with what Allah gave him, with the lawful rather than the forbidden and with permitted earnings rather than forbidden ones, and that is better for him, as in 'what Allah leaves is better for you'; in it is blessing and increase of provision that is not found in scrambling for forbidden means, which brings ruin and the opposite of blessing."}]},{"id":"mizan","ch":"amana","t":"إقامة الوزن بالقسط","e":"الأمر بإقامة الوزن بالقسط وإيفاء الكيل.","ay":[[55,7,9],[17,35,35]],"q":[{"bk":"saadi","s":55,"ay":9,"x":"{وأقيموا الوزنَ بالقسطِ}؛ أي: اجعلوه قائماً بالعدل، الذي تصل إليه مقدرتكم وإمكانكم، {ولا تُخۡسِروا الميزانَ}؛ أي: لا تنقصوه وتعملوا بضدِّه، وهو الجور والظلم والطغيان.","w":"السعدي","en":"Al-Sa'di: 'and keep the weight with justice' means make it upright with the justice within your ability; 'and do not make the balance fall short' means do not reduce it or do the opposite, which is injustice, wrongdoing and transgression."}]},{"id":"tayyib","ch":"amana","t":"الحلال الطيب في الرزق","e":"الأمر بالأكل من الحلال الطيب ومن طيبات الرزق.","ay":[[2,168,168],[5,88,88],[23,51,51]],"q":[{"bk":"saadi","s":2,"ay":168,"x":"هذا خطاب للناس كلهم مؤمنهم وكافرهم، فامتن عليهم بأن أمرهم أن يأكلوا من جميع ما في الأرض من حبوب وثمار وفواكه وحيوانات حالة كونها {حلالاً}؛ أي: محللاً لكم تناوله ليس بغصب ولا سرقة ولا محصلاً بمعاملة محرمة أو على وجه محرم أو معيناً على محرم {طيباً}؛ أي: ليس بخبيث كالميتة والدم ولحم الخنزير والخبائث كلها. ففي هذه الآية دليل على أن الأصل في الأعيان الإباحة أكلاً وانتفاعاً وأن المحرم نوعان: إما محرم لذاته وهو الخبيث الذي هو ضد الطيب، وإما محرم لما عرض له وهو المحرم لتعلق حق الله أو حق عباده به، وهو ضد الحلال.","w":"السعدي","en":"Al-Sa'di: this is addressed to all people, believer and disbeliever: Allah commanded them to eat of everything on earth of grains, fruits, and animals while it is lawful, meaning not taken by seizure, theft, a forbidden dealing, or in a forbidden way or to help a forbidden thing, and good, meaning not impure like carrion, blood, pork and all impure things. The verse shows that the default for things is permission, and that forbidden things are of two kinds: forbidden in themselves, the impure, which is the opposite of good, and forbidden because of something that befell them, through the right of Allah or of His servants, which is the opposite of lawful."},{"bk":"saadi","s":23,"ay":51,"x":"هذا أمرٌ منه تعالى لرسلِهِ بأكل الطيِّبات التي هي: الرزق والطيِّبُ الحلال، والشكر للَّه بالعمل الصالح الذي به يَصْلُحُ القلب والبدن والدنيا والآخرة، ويخبِرُهم أنَّه بما يعملون عليم؛ فكلُّ عمل عملوه وكلُّ سعي اكتسبوه؛ فإنَّ الله يعلمه، وسيجازيهم عليه أتمَّ الجزاء وأفضلَه، فدلَّ هذا على أنَّ الرسل كلَّهم متفقون على إباحة الطيبات من المآكل وتحريم الخبائثِ منها، وأنَّهم متَّفقون على كلِّ عمل صالح، وإنْ تنوَّعت بعضُ أجناس المأموراتِ واختلفتْ بها الشرائعُ؛ فإنَّها كلَّها عملٌ صالح، ولكنْ تتفاوت بتفاوتِ الأزمنة.","w":"السعدي","en":"Al-Sa'di: this is Allah's command to His messengers to eat the good things, which are the lawful, good provision, and to give thanks to Allah by righteous work, through which heart, body, this world and the next are set right; and He tells them He knows what they do, so every work they did and every effort they earned, Allah knows and will repay them with the fullest and best repayment; this shows that the messengers all agree on permitting good foods and forbidding the impure, and on every righteous work."}]},{"id":"ujra","ch":"amana","t":"الأجر والإجارة ووفاء العامل","e":"الأجر في العقد وما استُحق على العمل.","ay":[[28,27,28],[18,77,77]],"q":[{"bk":"saadi","s":28,"ay":26,"x":"فَـ {قَالَ} صاحبُ مَدْيَنَ لموسى: {إنِّي أريدُ أن أُنكِحَكَ إحدى ابنتيَّ هاتينِ على أن تَأجُرَني}؛ أي: تصير أجيراً عندي {ثماني حِجَجٍ}؛ أي: ثماني سنين، {فإنۡ أتممتَ عشراً فمن عندِكَ}: تبرُّع منك لا شيء واجبٌ عليك. {وما أريدُ أن أشُقَّ عليك}: فأحتِّم عشرَ السنين، أو ما أريد أن أستأجِرَك لأكلِّفَكَ أعمالاً شاقَّة، وإنَّما استأجرتُك لعمل سهل يسيرٍ لا مشقَّةَ فيه.","w":"السعدي","en":"Al-Sa'di: the man of Madyan said to Musa: 'I want to marry you to one of these two daughters on condition that you work for me eight years'; if you complete ten, that is a favour from you, not an obligation; 'and I do not wish to make it hard for you': I do not want to impose ten years, nor to hire you for burdensome work, but for easy work without hardship."},{"bk":"qurtubi","s":18,"ay":77,"x":"فَقَالَ مُوسَى لِلْخَضِرِ: \"لَوْ شِئْتَ لَاتَّخَذْتَ عَلَيْهِ أَجْراً\" لِأَنَّهُ فِعْلٌ يَسْتَحِقُّ أَجْرًا.","w":"القرطبي","en":"Al-Qurtubi: Musa said to al-Khidr 'if you wished, you could have taken a wage for it', because it is an act that deserves a wage."}]},{"id":"taaffuf","ch":"amana","t":"التعفف وصون النفس عن المسألة","e":"وصف المتعففين الذين لا يسألون الناس إلحافاً.","ay":[[2,273,273]],"q":[{"bk":"ibnkathir","s":2,"ay":273,"x":"وَقَوْلُهُ: ﴿لَا يَسْأَلُونَ النَّاسَ إِلْحَافًا﴾ أَيْ: لَا يُلحْون فِي الْمَسْأَلَةِ وَيُكَلِّفُونَ النَّاسَ مَا لَا يَحْتَاجُونَ إِلَيْهِ، فَإِنَّ مَنْ سَأَلَ وَلَهُ مَا يُغْنِيهِ عَنِ السُّؤَالِ، فَقَدْ أَلْحَفَ فِي الْمَسْأَلَةِ …","w":"ابن كثير","en":"Ibn Kathir: 'they do not ask people insistently' means they do not press in asking nor burden people with what they do not need; whoever asks while having what suffices him has pressed in asking."},{"bk":"qurtubi","s":2,"ay":273,"x":"وَرَوَى النَّسَائِيُّ وَمُسْلِمٌ عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: \"لَيْسَ الْمِسْكِينُ الَّذِي تَرُدُّهُ التَّمْرَةُ وَالتَّمْرَتَانِ وَاللُّقْمَةُ وَاللُّقْمَتَانِ إِنَّمَا الْمِسْكِينُ الْمُتَعَفِّفُ اقرءوا إن شئتم\" لا يَسْئَلُونَ النَّاسَ إِلْحافاً\".","w":"القرطبي","en":"Al-Qurtubi: al-Nasa'i and Muslim reported from Abu Hurayra that the Messenger of Allah said: 'The poor man is not the one who is turned away by one date or two or one morsel or two; the poor man is the one who keeps his dignity; read, if you wish: they do not ask people insistently.'"}]},{"id":"musa","ch":"qasas","t":"موسى عليه السلام: السقي والرعي والإجارة","e":"سقي موسى عليه السلام للمرأتين ثم عمله أجيراً في مدين.","ay":[[28,23,28]],"q":[{"bk":"saadi","s":28,"ay":24,"x":"فرقَّ لهما موسى عليه السلام ورحِمَهما، {فسقى لهما}: غير طالبٍ منهما الأجرَ، ولا له قصدٌ غيرَ وجه الله تعالى، فلما سقى لهما، وكان ذلك وقت شدة حرِّ وسط النهار؛ بدليل قوله:{ثمَّ تولَّى إلى الظِّلِّ}؛ مستريحاً لتلك الظلال بعد التعب، {فقال} في تلك الحالة مسترزقاً ربَّه: {ربِّ إنِّي لما أنزلتَ إليَّ من خيرٍ فقيرٌ}؛ أي: إنِّي مفتقرٌ للخير الذي تسوقُهُ إليَّ وتيسِّرُه لي، وهذا سؤالٌ منه بحالِهِ، والسؤال بالحال أبلغُ من السؤال بلسان المقال.","w":"السعدي","en":"Al-Sa'di: Musa pitied the two women and watered for them, seeking no pay and wanting only Allah's face; at midday in great heat he withdrew to the shade, resting after the toil, and in that state asked his Lord for provision: 'My Lord, I am in need of whatever good You send down to me'; this is asking by one's state, which is more eloquent than asking in words."},{"bk":"ibnkathir","s":28,"ay":23,"x":"قَالَ اللَّهُ تَعَالَى: ﴿فَسَقَى لَهُمَا﴾ قَالَ أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ: حَدَّثَنَا عَبْدُ اللَّهِ، أَنْبَأَنَا إسرائيل، عن أبى إسحاق، عن عَمْرو بْنِ مَيْمُونٍ الأوْدي، عَنْ عُمَرَ بْنِ الْخَطَّابِ، رَضِيَ اللَّهُ عَنْهُ، أَنْ مُوسَى، عَلَيْهِ السَّلَامُ، لَمَّا وَرَدَ مَاءَ مَدْيَنَ، وَجَدَ عَلَيْهِ أُمَّةً مِنَ النَّاسِ يَسْقُونَ، قَالَ: فَلَمَّا فَرَغُوا أَعَادُوا الصَّخْرَةَ عَلَى الْبِئْرِ، وَلَا يُطِيقُ رَفْعَهَا إِلَّا عَشَرَةُ رِجَالٍ …","w":"ابن كثير","en":"Ibn Kathir: Umar said that when Musa reached the water of Madyan he found a group of people watering; when they finished they put the rock back over the well, and only ten men could lift it …"}]},{"id":"dawud","ch":"qasas","t":"داود عليه السلام: صنعة الدروع وعمل اليد","e":"إلانة الحديد لداود وصنعته الدروع وعمله بيده.","ay":[[34,10,11],[21,80,80]],"q":[{"bk":"ibnkathir","s":34,"ay":10,"x":"فَعِنْدَ ذَلِكَ نَصَبَ دَاوُدُ، عَلَيْهِ السَّلَامُ، إِلَى رَبِّهِ فِي الدُّعَاءِ أَنْ يُعَلِّمَهُ عَمَلًا بِيَدِهِ يَسْتَغْنِي بِهِ وَيُغْنِي بِهِ عِيَالَهُ، فَأَلَانَ لَهُ الْحَدِيدَ، وَعَلَّمَهُ صَنْعَةَ الدُّرُوعِ، فَعَمَلَ الدِّرْعَ ، وَهُوَ أَوَّلُ مَنْ عَمِلَهَا، فَقَالَ اللَّهُ: ﴿أَنِ اعْمَلْ سَابِغَاتٍ وَقَدِّرْ فِي السَّرْدِ﴾ يَعْنِي: مَسَامِيرَ الْحَلَقِ، قَالَ: وَكَانَ يَعْمَلُ الدِّرْعَ ، فَإِذَا ارْتَفَعَ مِنْ عَمَلِهِ دِرْعٌ بَاعَهَا، فَتَصَدَّقَ بِثُلْثِهَا، وَاشْتَرَى بِثُلْثِهَا مَا يَكْفِيهِ وَعِيَالَهُ، وَأَمْسَكَ الثُّلُثَ يَتَصَدَّقُ بِهِ يَوْمًا بِيَوْمٍ إِلَى أَنْ يَعْمَلَ غَيْرَهَا","w":"ابن كثير","en":"Ibn Kathir: Dawud asked his Lord to teach him a work with his hands by which he and his family would be independent, so Allah softened iron for him and taught him to make coats of mail, and he was the first to make them; whenever a coat of mail was finished he sold it, gave a third in charity, bought what sufficed him and his family with a third, and kept a third to give in charity day by day until he made another."},{"bk":"qurtubi","s":21,"ay":80,"x":"وَقَدْ أَخْبَرَ اللَّهُ تَعَالَى عَنْ نَبِيِّهِ دَاوُدَ عَلَيْهِ السَّلَامُ أَنَّهُ كَانَ يَصْنَعُ الدُّرُوعَ، وَكَانَ أَيْضًا يَصْنَعُ الْخُوصَ، وَكَانَ يَأْكُلُ مِنْ عَمَلِ يَدِهِ، وَكَانَ آدَمُ حَرَّاثًا، وَنُوحٌ نَجَّارًا وَلُقْمَانُ خَيَّاطًا، وَطَالُوتُ دَبَّاغًا.","w":"القرطبي","en":"Al-Qurtubi: Allah told of His prophet Dawud that he made coats of mail and also made palm-leaf work and ate from the work of his hands; Adam was a farmer, Nuh a carpenter, Luqman a tailor and Talut a tanner."},{"bk":"saadi","s":34,"ay":10,"x":"ومن فضله عليه أن ألانَ له الحديدَ؛ ليعملَ الدروع السابغاتِ، وعلَّمه تعالى كيفيَّة صنعتِهِ؛ بأن يقدِّرَه في {السردِ}؛ أي: يقدِّره حَلَقاً ويصنعُه كذلك ثم يُدْخِلُ بعضها ببعض، قال تعالى:{وعلَّمۡناه صنعةَ لَبوس لكم لِتُحۡصِنَكُم من بأسِكُم فهل أنتم شاكرونَ}، ولمَّا ذَكَرَ ما امتنَّ به عليه وعلى آله؛ أمره بشكرِهِ وأن يَعْمَلوا صالحاً، ويراقِبوا الله تعالى فيه بإصلاحه وحفظِهِ من المفسداتِ؛ فإنَّه بصيرٌ بأعمالهم، مطَّلع عليها، لا يخفى عليه منها شيءٌ.","w":"السعدي","en":"Al-Sa'di: part of His favour to him is that He softened iron so he could make full coats of mail and taught him how to make them, by measuring them in rings and linking them; then He ordered him and his family to give thanks, to work righteousness and to be mindful of Allah in it by doing it well and guarding it from what spoils it, for He sees their work."}]},{"id":"ale","ch":"qasas","t":"«اعملوا آل داود شكراً»: العمل شكرٌ لله","e":"الأمر لآل داود بالعمل شكراً بعد ذكر ما سُخِّر لسليمان من الصنائع.","ay":[[34,12,13]],"q":[{"bk":"saadi","s":34,"ay":12,"x":"أي: كالبرك الكبار يعملونها لسليمان للطعام؛ لأنَّه يحتاجُ إلى ما لا يحتاج إليه غيره. {و} يعملونَ له قدوراً {راسياتٍ}: لا تُزالُ عن أماكِنِها من عِظَمِها، فلما ذكر مِنَّتَه عليهم؛ أمَرَهم بشكرها، فقال:{اعۡمَلوا آل داودَ}: وهم داودُ وأولادهُ وأهلُه؛ لأنَّ المنَّةَ على الجميع، وكثير من هذه المصالح عائدٌ لكلِّهم {شُكراً}: لله على ما أعطاهم، ومقابلةً لما أولاهم.","w":"السعدي","en":"Al-Sa'di: they made large basins like pools for Sulayman, for food, because he needs what others do not, and fixed cauldrons that cannot be moved from their places because of their size; after He mentioned His favour He ordered them to be thankful: 'Work, family of Dawud, in gratitude', for the favour was on all of them, and many of these benefits returned to all of them."}]},{"id":"nuh","ch":"qasas","t":"نوح عليه السلام وصناعة السفينة","e":"أمر نوح عليه السلام بصنع الفلك وصنعه له وسخرية قومه.","ay":[[11,37,38],[23,27,27]],"q":[{"bk":"ibnkathir","s":11,"ay":37,"x":"﴿وَاصْنَعِ الْفُلْكَ﴾ يَعْنِي: السَّفِينَةَ ﴿بِأَعْيُنِنَا﴾ أَيْ: بِمَرْأَى مِنَّا، ﴿وَوَحْيِنَا﴾ أَيْ: وَتَعْلِيمِنَا لَكَ مَاذَا تَصْنَعُهُ، ﴿وَلا تُخَاطِبْنِي فِي الَّذِينَ ظَلَمُوا إِنَّهُمْ مُغْرَقُونَ﴾ .","w":"ابن كثير","en":"Ibn Kathir: 'and build the ark', meaning the ship, 'under Our eyes', meaning in Our sight, 'and Our revelation', meaning Our teaching you what to build; 'and do not address Me concerning those who did wrong; they will be drowned.'"},{"bk":"saadi","s":11,"ay":37,"x":"فامتثلَ أمر ربِّه، وجَعَلَ يصنع الفلك، {وكلما مرَّ عليه ملأ من قومِهِ}: ورأوا ما يصنع، {سَخِروا منه قال إن تَسۡخَروا منَّا}: الآن، {فإنَّا نسخَرُ منكم كما تسخَرونَ}.","w":"السعدي","en":"Al-Sa'di: he obeyed his Lord's command and began building the ark, and whenever a group of his people passed by and saw what he was making, they mocked him; he said: 'If you mock us now, we will mock you as you mock.'"}]},{"id":"dhulqarnayn","ch":"qasas","t":"ذو القرنين وبناء السد بالقوة والحديد","e":"طلب القوم بناء السد وإجابة ذي القرنين وبناؤه بالحديد والقِطر.","ay":[[18,94,97]],"q":[{"bk":"saadi","s":18,"ay":95,"x":"فلم يكن ذو القرنين ذا طمع ولا رغبةٍ في الدُّنيا ولا تاركاً لإصلاح أحوال الرعيَّة، بل قصدُهُ الإصلاح؛ فلذلك أجاب طلبتهم؛ لما فيها من المصلحة، ولم يأخذ منهم أجرةً، وشَكَرَ ربَّه على تمكينه واقتداره، فقال لهم:{ما مَكَّنِّي فيه ربِّي خيرٌ}؛ أي: مما تبذلون لي وتعطوني، وإنَّما أطلب منكم أن تعينوني بقوَّةٍ منكم بأيديكم؛ {أجۡعَلۡ بينَكم وبينهم رَدۡماً}؛ أي: مانعاً من عبورهم عليكم.","w":"السعدي","en":"Al-Sa'di: Dhul-Qarnayn was not greedy and had no desire for this world, nor did he neglect the people's affairs; his aim was to set things right, so he answered their request for the benefit in it and took no payment, thanking his Lord for His empowerment; he said: 'What my Lord has established me in is better' than what you offer; I ask only that you help me with your strength, your own hands, and I will put a barrier between you and them."},{"bk":"saadi","s":18,"ay":96,"x":"{آتوني زُبَرَ الحديدِ}؛ أي: قطع الحديد، فأعْطَوْه ذلك، {حتى إذا ساوى بين الصَّدَفين}؛ أي: الجبلين اللذين بُني بينهما السدُّ، {قال انفُخوا}: النار؛ أي أوقدوها إيقاداً عظيماً واستعملوا لها المنافيخ لتشتدَّ فتذيبَ النحاس، فلما ذاب النحاس الذي يريُد أن يُلْصِقَهُ بين زُبَرِ الحديد، {قال آتوني أفۡرِغۡ عليه قِطۡراً}؛ أي: نحاساً مذاباً، فأفرغ عليه القطر، فاستحكم السدُّ استحكاماً هائلاً، وامتنع به من وراءه من الناس من ضرر يأجوج ومأجوج.","w":"السعدي","en":"Al-Sa'di: 'Bring me sheets of iron', they brought them; 'until, when he had made it level between the two mountainsides, he said: Blow'; they blew the fire strongly with bellows until the copper melted; then he said 'bring me molten copper to pour over it', and the barrier became extremely firm and protected the people behind it from Yajuj and Majuj."}]},{"id":"yusuf","ch":"qasas","t":"يوسف عليه السلام وتخطيط الزراعة والتخزين","e":"تفسير رؤيا الملك وتدبير الزراعة والادخار في سني الخصب والجدب.","ay":[[12,47,49],[12,54,55]],"q":[{"bk":"saadi","s":12,"ay":47,"x":"فعبر يوسفُ السبعَ البقراتِ السمانَ والسبعَ السنبلاتِ الخضر بأنهنَّ سبع سنين مخصبات، والسبع البقرات العجاف والسبع السنبلات اليابساتِ بأنَّهنَّ سنين مجدباتٌ، ولعلَّ وجهَ ذلك ـ والله أعلم ـ أنَّ الخصب والجدب لما كان الحرث مبنيًّا عليه، وأنَّه إذا حصل الخصبُ؛ قويتِ الزروع والحروثُ وحَسُنَ منظرُها وكثُرت غلالها، والجدب بالعكس من ذلك، وكانت البقر هي التي تُحرث عليها الأرض وتُسقى عليها الحروث في الغالب، والسنبلاتُ هي أعظم الأقوات وأفضلها؛ عبرها بذلك لوجود المناسبة، فجمع لهم في تأويلها بين التعبير والإشارة لما يفعلونه ويستعدُّون به من التدبير في سني الخصب إلى سني الجَدْب، فقال:{تزرعونَ سبعَ سنينَ دأباً}؛ أي: متتابعاتٍ، {فما حصدتُم}: من تلك الزروع، {فذَروه}؛ أي: اتركوه {في سُنبُلِهِ}: لأنَّه أبقى له وأبعد من الالتفات إليه، {إلاَّ قليلاً مما تأكلون …","w":"السعدي","en":"Al-Sa'di: Yusuf interpreted the seven fat cows and seven green ears as seven fertile years, and the seven lean cows and seven dry ears as years of drought; in his interpretation he combined the explanation with the pointer to what they should do and prepare, in the years of plenty before the years of drought: 'you will farm for seven years consecutively; what you harvest, leave in its ear', meaning leave it in its ear because it keeps better and is less likely to be touched, 'except a little of what you eat' …"},{"bk":"ibnkathir","s":12,"ay":47,"x":"وَأَخْبَرَهُمْ أَنَّهُنَّ لَا يُنْبِتْنَ شَيْئًا، وَمَا بَذَرُوهُ فَلَا يَرْجِعُونَ مِنْهُ إِلَى شَيْءٍ؛ وَلِهَذَا قَالَ: ﴿يَأْكُلْنَ مَا قَدَّمْتُمْ لَهُنَّ إِلا قَلِيلا مِمَّا تُحْصِنُونَ﴾ ثُمَّ بَشَّرَهُمْ بَعْدَ الجَدْب الْعَامِ الْمُتَوَالِي بِأَنَّهُ يَعْقُبُهُمْ بَعْدَ ذَلِكَ ﴿عَامٌ فِيهِ يُغَاثُ النَّاسُ﴾ أَيْ: يَأْتِيهِمُ الْغَيْثُ، وَهُوَ المَطرُ، وتُغل الْبِلَادُ، ويَعصرُ النَّاسُ مَا كَانُوا يَعْصِرُونَ عَلَى عَادَتِهِمْ، مِنْ زَيْتٍ وَنَحْوِهُ، وَسُكَّرٍ وَنَحْوِهُ حَتَّى قَالَ بَعْضُهُمْ: يَدْخُلُ فِيهِ حَلْبُ اللَّبَنِ أَيْضًا.","w":"ابن كثير","en":"Ibn Kathir: he told them that the lean years would bring forth nothing and that what they sow would yield nothing, so 'they will consume what you stored for them, except a little of what you keep'; then he gave them good news that after those general years of drought would come 'a year in which the people will have rain', when the lands will give their produce and people will press as they used to, oil and sugar and the like."}]},{"id":"maryam","ch":"qasas","t":"«وهزي إليك بجذع النخلة»: الأخذ بالأسباب","e":"أمر مريم بهزّ جذع النخلة وهي في حال الولادة.","ay":[[19,25,25]],"q":[{"bk":"qurtubi","s":19,"ay":25,"x":"قَالَ عُلَمَاؤُنَا: لَمَّا كَانَ قَلْبُهَا فَارِغًا فَرَّغَ اللَّهُ جَارِحَتَهَا عَنِ النَّصَبِ، فَلَمَّا وَلَدَتْ عِيسَى وَتَعَلَّقَ قَلْبُهَا بِحُبِّهِ، وَاشْتَغَلَ سِرُّهَا بِحَدِيثِهِ وَأَمْرِهِ، وَكَلَهَا إِلَى كَسْبِهَا، وَرَدَّهَا إِلَى الْعَادَةِ بِالتَّعَلُّقِ بِالْأَسْبَابِ فِي عِبَادِهِ.","w":"القرطبي","en":"Al-Qurtubi: our scholars said: when her heart was empty, Allah emptied her limbs of toil; when she gave birth to Isa and her heart was attached to loving him and her inner self busy with his matter, He left her to her own earning and returned her to the usual way of relating to means among His servants."},{"bk":"saadi","s":19,"ay":25,"x":"{وهُزِّي إليك بجذع النخلةِ تُساقِطۡ عليك رُطَباً جنيًّا}؛ أي: طريًّا لذيذاً نافعاً.","w":"السعدي","en":"Al-Sa'di: 'and shake toward you the trunk of the palm tree; it will drop upon you ripe, fresh dates', meaning fresh, delicious and beneficial."}]},{"id":"safina","ch":"qasas","t":"أصحاب السفينة: مساكين يعملون في البحر","e":"سفينة مساكين يعملون في البحر في قصة الخضر وموسى.","ay":[[18,79,79],[18,82,82]],"q":[{"bk":"saadi","s":18,"ay":79,"x":"{أما السفينة}: التي خرقتها، {فكانتۡ لمساكينَ يعملون في البحر}: يقتضي ذلك الرِّقَّة عليهم والرأفة بهم، {فأردتُ أن أَعِيبها وكان وراءَهُم مَلِكٌ يأخذ كلَّ سفينة غَصۡباً}؛ أي: كان مرورهم على ذلك الملك الظالم؛ فكلُّ سفينة صالحةٍ تمرُّ عليه ما فيها عيبٌ غَصَبها وأخَذَها ظلماً، فأردتُ أن أخْرِقها ليكونَ فيها عيبٌ فتسلم من ذلك الظالم.","w":"السعدي","en":"Al-Sa'di: 'As for the boat, it belonged to poor people working at sea', and this calls for tenderness and kindness toward them; 'I wanted to damage it, for behind them was a king seizing every good boat by force', meaning their route passed by that unjust king, who would take any sound boat without a flaw, so I wanted to give it a flaw so that it would be safe from him."},{"bk":"saadi","s":18,"ay":79,"x":"ومنها: أنَّ المسكين قد يكون له مالٌ لا يبلُغ كفايته ولا يخرجُ بذلك عن اسم المسكنة؛ لأنَّ الله أخبر أنَّ هؤلاء المساكين لهم سفينة.","w":"السعدي","en":"Al-Sa'di: among the lessons is that a poor man may own property that does not reach his needs and still not leave the name of poor, because Allah said these poor men had a boat."}]},{"id":"tathaqul","ch":"kasal","t":"التثاقل إلى الأرض وترك النفير","e":"عتاب الذين تثاقلوا إلى الأرض حين دُعوا إلى النفير.","ay":[[9,38,39]],"q":[{"bk":"ibnkathir","s":9,"ay":38,"x":"هَذَا شُرُوعٌ فِي عِتَابِ مَنْ تخلَّف عَنْ رَسُولِ اللَّهِ ﷺ فِي غَزْوَةِ تَبُوكَ، حِينَ طَابَتِ الثِّمَارُ وَالظِّلَالُ فِي شِدَّةِ الْحَرِّ وحَمَارَّة الْقَيْظِ، فَقَالَ تَعَالَى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا مَا لَكُمْ إِذَا قِيلَ لَكُمُ انْفِرُوا فِي سَبِيلِ اللَّهِ﴾ أَيْ: إِذَا دُعِيتُمْ إِلَى الْجِهَادِ فِي سَبِيلِ اللَّهِ ﴿اثَّاقَلْتُمْ إِلَى الأرْضِ﴾ أَيْ: تَكَاسَلْتُمْ وَمِلْتُمْ إِلَى الْمَقَامِ فِي الدَّعَةِ وَالْخَفْضِ وَطَيِّبِ الثِّمَارِ، ﴿أَرَضِيتُمْ بِالْحَيَاةِ الدُّنْيَا مِنَ الآخِرَةِ﴾ أَيْ: مَا لَكُمْ فَعَلْتُمْ هَكَذَا أَرِضًا مِنْكُمْ بِالدُّنْيَا بَدَلًا مِنَ الْآخِرَةِ ثُمَّ زَهَّدَ تَبَارَكَ وَتَعَالَى فِي الدُّنْيَا، وَرَغَّبَ فِي الْآخِرَةِ، فَقَالَ: ﴿فَمَا مَتَاعُ الْحَيَاةِ الدُّنْيَا فِي الآخِرَةِ إِلا قَلِيلٌ﴾ كَمَا قَالَ الْإِمَامُ أَحْمَدُ.","w":"ابن كثير","en":"Ibn Kathir: this begins the rebuke of those who stayed behind from the Messenger of Allah at Tabuk, when the fruits were ripe and the shade pleasant in the heat of summer; Allah said: 'What is the matter with you that when you are told to go out in the cause of Allah, you cling heavily to the ground?', meaning when you were called to jihad you grew lazy and inclined to stay in comfort and ease and good fruit; 'Are you content with the life of this world over the Hereafter?'"}]},{"id":"faragh","ch":"kasal","t":"«فإذا فرغت فانصب»: لا فراغ بلا عمل","e":"الأمر بالنصب والاجتهاد إذا فُرغ من الشغل.","ay":[[94,7,8]],"q":[{"bk":"saadi","s":94,"ay":7,"x":"ثم أمر [اللَّهُ] رسوله أصلاً والمؤمنين تبعاً بشكره والقيام بواجب نعمه، فقال:{فإذا فرَغۡتَ فانصَبۡ}؛ أي: إذا تفرَّغْتَ من أشغالِك، ولم يبقَ في قلبكَ ما يعوقه؛ فاجتهدْ في العبادة والدُّعاء، {وإلى ربِّك}: وحده {فارغَبۡ}؛ أي: أعظم الرغبة في إجابة دعائك وقبول دعواتك ، ولا تكنْ ممَّن إذا فرغوا ؛ لعبوا وأعرضوا عن ربِّهم وعن ذِكْرِه، فتكون من الخاسرين.","w":"السعدي","en":"Al-Sa'di: Allah then ordered His Messenger first and the believers after him to thank Him and fulfil what His favours require: 'So when you are free, strive', meaning when you are free from your tasks and nothing remains in your heart to hinder it, exert yourself in worship and prayer; 'and to your Lord alone direct your longing', and do not be among those who play and turn away from their Lord and remembrance of Him when they are free, for then you would be among the losers."}]},{"id":"tawakkul","ch":"kasal","t":"التوكل مع الأخذ بالأسباب","e":"التوكل بعد العزم، وأن الله لا يغيّر ما بقوم حتى يغيروا ما بأنفسهم.","ay":[[3,159,159],[13,11,11]],"q":[{"bk":"saadi","s":3,"ay":159,"x":"ثم قال تعالى:{فإذا عزمت}؛ أي: على أمر من الأمور بعد الاستشارة فيه إن كان يحتاج إلى استشارة {فتوكل على الله}؛ أي: اعتمد على حول الله وقوته متبرئاً من حولك وقوتك، {إن الله يحب المتوكلين} عليه اللاجئين إليه.","w":"السعدي","en":"Al-Sa'di: 'when you have decided', that is, on a matter after consultation if it needs consultation, 'then rely on Allah', meaning depend on Allah's power and strength, declaring yourself free of your own; 'indeed Allah loves those who rely on Him', who take refuge in Him."},{"bk":"saadi","s":13,"ay":11,"x":"من النعمة والإحسان ورَغَدِ العيش، {حتَّى يغيِّروا ما بأنفسِهم}: بأن ينتقلوا من الإيمان إلى الكفر، ومن الطاعة إلى المعصية، أو من شكر نعم الله إلى البطر بها، فيسلُبُهم الله عند ذلك إياها، وكذلك إذا غير العباد ما بأنفسهم من المعصية، فانتقلوا إلى طاعة الله؛ غيَّر الله عليهم ما كانوا فيه من الشقاء إلى الخير والسرور والغبطة والرحمة.","w":"السعدي","en":"Al-Sa'di: Allah does not change what is with a people of blessing, goodness and ease of life until they change what is in themselves, by moving from faith to disbelief, from obedience to disobedience, or from thanks for Allah's blessings to being insolent with them, and then He takes them away; likewise if people change what is in themselves from disobedience to obedience, Allah changes their hardship to good, joy and mercy."}]},{"id":"iqtisad","ch":"kasal","t":"الاقتصاد في الإنفاق بين الإسراف والتقتير","e":"النهي عن غل اليد وبسطها كل البسط، ووصف عباد الرحمن في الإنفاق.","ay":[[17,29,29],[25,67,67]],"q":[{"bk":"saadi","s":25,"ay":67,"x":"{والذين إذا أنفَقوا}: النفقاتِ الواجبةَ والمستحبةَ {لم يُسۡرِفوا}: بأن يَزيدوا على الحدِّ فيدخُلوا في قسم التبذير، {ولم يَقۡتُروا}: فيدخلوا في باب البُخْل والشُّحِّ، وإهمال الحقوق الواجبة، {وكان}: إنفاقُهم {بينَ ذلك}: بين الإسراف والتقتير {قَواماً}: يبذُلون في الواجبات من الزَّكَواتِ والكفاراتِ والنفقاتِ الواجبةِ وفيما ينبغي على الوجه الذي يَنْبَغي من غير ضررٍ ولا ضِرارٍ، وهذا من عدلهم واقتصادهم.","w":"السعدي","en":"Al-Sa'di: 'those who, when they spend,' whether on what is obligatory or recommended, 'are neither extravagant', exceeding the limit and entering waste, 'nor niggardly', falling into stinginess and neglecting due rights, 'and between that they are moderate', spending on obligations like zakat, expiations and required maintenance and on what is fitting, in the proper way, without harm or injury; this is part of their justice and moderation."},{"bk":"ibnkathir","s":17,"ay":29,"x":"يَقُولُ تَعَالَى آمِرًا بِالِاقْتِصَادِ فِي الْعَيْشِ ذَامًّا لِلْبُخْلِ نَاهِيًا عَنِ السَّرَف: ﴿وَلا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَى عُنُقِكَ﴾ أَيْ: لَا تَكُنْ بَخِيلًا مَنُوعًا، لَا تُعْطِي أَحَدًا شَيْئًا، كَمَا قَالَتِ الْيَهُودُ عَلَيْهِمْ لَعَائِنُ اللَّهِ: ﴿يَدُ اللَّهِ مَغْلُولَةٌ﴾ [الْمَائِدَةِ: ٦٤] أَيْ نَسَبُوهُ إِلَى الْبُخْلِ، تَعَالَى وَتَقَدَّسَ الْكَرِيمُ الْوَهَّابُ.","w":"ابن كثير","en":"Ibn Kathir: Allah commands moderation in living, condemning stinginess and forbidding extravagance: 'Do not make your hand chained to your neck', meaning do not be a tightfisted withholder who gives nothing to anyone, as the Jews, may Allah's curses be on them, said 'Allah's hand is chained', attributing stinginess to Him, exalted is the Generous, the Bestower."}]},{"id":"tulhihim","ch":"kasal","t":"رجال لا تلهيهم تجارة ولا بيع عن ذكر الله","e":"رجال تجارتهم وبيعهم لا يشغلهم عن ذكر الله وإقام الصلاة.","ay":[[24,37,37],[63,9,9]],"q":[{"bk":"saadi","s":24,"ay":37,"x":"ليسوا ممَّن يؤثِرُ على ربِّه دنيا ذات لذاتٍ ولا تجارةٍ ومكاسبَ مشغلة عنه. {لا تُلهيهم تجارةٌ}: وهذا يَشْمَلُ كلَّ تكسُّب يُقصد به العِوَضُ، فيكون قوله:{ولا بَيۡعٌ}: من باب عطف الخاصِّ على العامِّ؛ لكَثرة الاشتغال بالبيع على غيره؛ فهؤلاء الرجال وإن اتَّجروا وباعوا واشْتَرَوا؛ فإنَّ ذلك لا محذور فيه، لكنَّه لا تلهيهم تلك بأن يقدِّموها ويؤثِروها على {ذِكۡر الله وإقام الصَّلاةِ وإيتاءِ الزكاة}: بل جعلوا طاعةَ الله وعبادتَه غايةَ مرادِهم ونهايةَ مقصدِهم؛ فما حال بينَهم وبينَها رفضوه.","w":"السعدي","en":"Al-Sa'di: they are not people who prefer a world of pleasures, trade or distracting earnings over their Lord; 'neither trade' covers every earning sought for an exchange, and 'nor sale' is a specific mention after the general because of how much people busy themselves with selling; such men may trade, sell and buy and there is no harm in that, but these things do not distract them by being put first and preferred over 'remembering Allah, establishing prayer and giving zakat'; they make obedience and worship of Allah their main goal and final aim, so whatever came between them and it they gave up."},{"bk":"qurtubi","s":24,"ay":37,"x":"(تِجارَةٌ وَلا بَيْعٌ عَنْ ذِكْرِ اللَّهِ) خَصَّ التِّجَارَةَ بِالذِّكْرِ لأنها أعظم ما يشتغل به الْإِنْسَانُ عَنِ الصَّلَاةِ.","w":"القرطبي","en":"Al-Qurtubi: trade is singled out for mention because it is the greatest thing that people busy themselves with away from prayer."}]},{"id":"qarun","ch":"kasal","t":"قارون: «إنما أوتيته على علم عندي»","e":"قول قارون إنما أوتيته على علم عندي ونصح قومه له.","ay":[[28,76,78]],"q":[{"bk":"saadi","s":28,"ay":77,"x":"فَـ {قَالَ} قارونُ رادًّا لنصيحتِهِم كافراً لنعمةِ ربِّه: {إنَّما أوتيتُهُ على علم عندي}؛ أي: إنَّما أدركتُ هذه الأموالَ بكسبي ومعرفتي بوجوه المكاسب وحِذْقي. أو: على علم من اللهِ بحالي؛ يعلمُ أنِّي أهلٌ لذلك؛ فلم تنصحوني على ما أعطاني الله؟!","w":"السعدي","en":"Al-Sa'di: Qarun answered their advice by rejecting it and denying his Lord's favour: 'I was only given it through knowledge I have', meaning I only gained this wealth through my own earning, my knowledge of the ways of earning and my skill; or through knowledge from Allah of my state, that I deserve it; so why do you advise me about what Allah gave me?"}]},{"id":"laudiu","ch":"ajr","t":"«إني لا أضيع عمل عامل منكم»","e":"إجابة الله دعاء المؤمنين بأنه لا يضيع عمل عامل منهم.","ay":[[3,195,195]],"q":[{"bk":"saadi","s":3,"ay":195,"x":"أي: أجاب الله دعاءهم دعاء العبادة ودعاء الطلب وقال: {إني لا أُضيع عمل عامل منكم من ذكر أو أنثى} فالجميع سيلقون ثواب أعمالهم كاملاً موفراً، أي: كلكم على حد سواء في الثواب والعقاب …","w":"السعدي","en":"Al-Sa'di: Allah answered their prayer, of worship and of asking, and said: 'I will not let any deed of a worker among you be lost, male or female'; all will meet the reward of their deeds complete and in full, and all of you are equal in reward and in punishment …"}]},{"id":"mithqal","ch":"ajr","t":"مثقال ذرة من الخير: لا يضيع عمل","e":"رؤية العامل جزاء مثقال الذرة من الخير والشر.","ay":[[99,7,8]],"q":[{"bk":"saadi","s":99,"ay":7,"x":"{فمَن يعملۡ مثقال ذرَّةٍ خيراً يَرَهُ. ومَن يعملۡ مثقال ذرَّةٍ شرًّا يَرَهُ}: وهذا شامل عامٌّ للخير والشرِّ كلِّه؛ لأنَّه إذا رأى مثقال الذَّرَّة التي هي أحقر الأشياء، وجوزي عليها؛ فما فوق ذلك من باب أولى وأحرى؛ كما قال تعالى:{يومَ تجدُ كلُّ نفسٍ ما عملتۡ من خيرٍ محضَراً وما عملتۡ من سوءٍ تودُّ لو أنَّ بينها وبينه أمداً بعيداً}، {ووجدوا ما عملوا حاضراً}، وهذا فيه الترغيب في فعل الخير، ولو قليلاً، والترهيب من فعل الشر، ولو حقيراً.","w":"السعدي","en":"Al-Sa'di: 'whoever does an atom's weight of good will see it, and whoever does an atom's weight of evil will see it' is general for all good and evil, since if one sees the weight of an atom, the smallest of things, and is repaid for it, then what is above it is more fitting; this encourages doing good, even a little, and warns against doing evil, even something small."}]},{"id":"hayat","ch":"ajr","t":"الحياة الطيبة جزاء العامل الصالح","e":"وعد الله من عمل صالحاً وهو مؤمن بحياة طيبة وأجر.","ay":[[16,97,97]],"q":[{"bk":"saadi","s":16,"ay":97,"x":"ولهذا ذكر جزاء العاملين في الدُّنيا والآخرة فقال: {مَنۡ عمل صالحاً من ذَكَرٍ أو أنثى وهو مؤمنٌ}: فإنَّ الإيمان شرطٌ في صحَّة الأعمال الصالحة وقَبولها، بل لا تسمَّى أعمالاً صالحة إلاَّ بالإيمان، والإيمان مقتضٍ لها؛ فإنَّه التصديق الجازم المثمِرُ لأعمال الجوارح من الواجبات والمستحبَّات؛ فمَنْ جَمَعَ بين الإيمان والعمل الصالح؛ {فَلَنُحۡيِيَنَّهُ حياةً طيبةً}: وذلك بطمأنينة قلبه وسكون نفسه وعدم التفاتِهِ لما يُشَوِّش عليه قلبه ويرزُقُه الله رزقاً حلالاً طيّباً من حيث لا يحتسب. {ولنجزِيَنَّهم}: في الآخرة {أجرَهم بأحسنِ ما كانوا يعملونَ}: من أصناف اللذَّات؛ ممَّا لا عينٌ رأتْ، ولا أذنٌ سمعتْ، ولا خطرَ على قلب بشر، فيؤتيه الله في الدُّنيا حسنةً وفى الآخرة حسنةً.","w":"السعدي","en":"Al-Sa'di: Allah mentions the reward of workers in this world and the next: 'whoever does righteousness, male or female, while a believer'; faith is a condition for righteous deeds to be valid and accepted; whoever combines faith and righteous work, 'We will surely cause him to live a good life', that is, with a reassured heart, a calm soul, and no turning toward what disturbs his heart, and Allah gives him lawful, good provision from where he does not expect."}]}],"ay":{"174":"يَٰٓأَيُّهَا ٱلنَّاسُ كُلُواْ مِمَّا فِي ٱلۡأَرۡضِ حَلَٰلٗا طَيِّبٗا وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٌ","204":"لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَبۡتَغُواْ فَضۡلٗا مِّن رَّبِّكُمۡۚ فَإِذَآ أَفَضۡتُم مِّنۡ عَرَفَٰتٖ فَٱذۡكُرُواْ ٱللَّهَ عِندَ ٱلۡمَشۡعَرِ ٱلۡحَرَامِۖ وَٱذۡكُرُوهُ كَمَا هَدَىٰكُمۡ وَإِن كُنتُم مِّن قَبۡلِهِۦ لَمِنَ ٱلضَّآلِّينَ","273":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِن طَيِّبَٰتِ مَا كَسَبۡتُمۡ وَمِمَّآ أَخۡرَجۡنَا لَكُم مِّنَ ٱلۡأَرۡضِۖ وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ تُنفِقُونَ وَلَسۡتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغۡمِضُواْ فِيهِۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَنِيٌّ حَمِيدٌ","279":"لِلۡفُقَرَآءِ ٱلَّذِينَ أُحۡصِرُواْ فِي سَبِيلِ ٱللَّهِ لَا يَسۡتَطِيعُونَ ضَرۡبٗا فِي ٱلۡأَرۡضِ يَحۡسَبُهُمُ ٱلۡجَاهِلُ أَغۡنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعۡرِفُهُم بِسِيمَٰهُمۡ لَا يَسۡـَٔلُونَ ٱلنَّاسَ إِلۡحَافٗاۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ","451":"فَبِمَا رَحۡمَةٖ مِّنَ ٱللَّهِ لِنتَ لَهُمۡۖ وَلَوۡ كُنتَ فَظًّا غَلِيظَ ٱلۡقَلۡبِ لَٱنفَضُّواْ مِنۡ حَوۡلِكَۖ فَٱعۡفُ عَنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمۡ وَشَاوِرۡهُمۡ فِي ٱلۡأَمۡرِۖ فَإِذَا عَزَمۡتَ فَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَوَكِّلِينَ","487":"فَٱسۡتَجَابَ لَهُمۡ رَبُّهُمۡ أَنِّي لَآ أُضِيعُ عَمَلَ عَٰمِلٖ مِّنكُم مِّن ذَكَرٍ أَوۡ أُنثَىٰۖ بَعۡضُكُم مِّنۢ بَعۡضٖۖ فَٱلَّذِينَ هَاجَرُواْ وَأُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأُوذُواْ فِي سَبِيلِي وَقَٰتَلُواْ وَقُتِلُواْ لَأُكَفِّرَنَّ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأُدۡخِلَنَّهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ ثَوَابٗا مِّنۡ عِندِ ٱللَّهِۚ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلثَّوَابِ","524":"وَلَا تَتَمَنَّوۡاْ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖۚ لِّلرِّجَالِ نَصِيبٞ مِّمَّا ٱكۡتَسَبُواْۖ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا ٱكۡتَسَبۡنَۚ وَسۡـَٔلُواْ ٱللَّهَ مِن فَضۡلِهِۦٓۚ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَيۡءٍ عَلِيمٗا","550":"۞ إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تُؤَدُّواْ ٱلۡأَمَٰنَٰتِ إِلَىٰٓ أَهۡلِهَا وَإِذَا حَكَمۡتُم بَيۡنَ ٱلنَّاسِ أَن تَحۡكُمُواْ بِٱلۡعَدۡلِۚ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓۗ إِنَّ ٱللَّهَ كَانَ سَمِيعَۢا بَصِيرٗا","756":"وَكُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلٗا طَيِّبٗاۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ أَنتُم بِهِۦ مُؤۡمِنُونَ","963":"وَلَقَدۡ مَكَّنَّٰكُمۡ فِي ٱلۡأَرۡضِ وَجَعَلۡنَا لَكُمۡ فِيهَا مَعَٰيِشَۗ قَلِيلٗا مَّا تَشۡكُرُونَ","1272":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَا لَكُمۡ إِذَا قِيلَ لَكُمُ ٱنفِرُواْ فِي سَبِيلِ ٱللَّهِ ٱثَّاقَلۡتُمۡ إِلَى ٱلۡأَرۡضِۚ أَرَضِيتُم بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا مِنَ ٱلۡأٓخِرَةِۚ فَمَا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا قَلِيلٌ","1273":"إِلَّا تَنفِرُواْ يُعَذِّبۡكُمۡ عَذَابًا أَلِيمٗا وَيَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّوهُ شَيۡـٔٗاۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ","1339":"وَقُلِ ٱعۡمَلُواْ فَسَيَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ وَٱلۡمُؤۡمِنُونَۖ وَسَتُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ","1509":"وَٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ","1510":"وَيَصۡنَعُ ٱلۡفُلۡكَ وَكُلَّمَا مَرَّ عَلَيۡهِ مَلَأٞ مِّن قَوۡمِهِۦ سَخِرُواْ مِنۡهُۚ قَالَ إِن تَسۡخَرُواْ مِنَّا فَإِنَّا نَسۡخَرُ مِنكُمۡ كَمَا تَسۡخَرُونَ","1556":"۞ وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ وَلَا تَنقُصُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَۖ إِنِّيٓ أَرَىٰكُم بِخَيۡرٖ وَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٖ مُّحِيطٖ","1557":"وَيَٰقَوۡمِ أَوۡفُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ","1642":"قَالَ تَزۡرَعُونَ سَبۡعَ سِنِينَ دَأَبٗا فَمَا حَصَدتُّمۡ فَذَرُوهُ فِي سُنۢبُلِهِۦٓ إِلَّا قَلِيلٗا مِّمَّا تَأۡكُلُونَ","1643":"ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ سَبۡعٞ شِدَادٞ يَأۡكُلۡنَ مَا قَدَّمۡتُمۡ لَهُنَّ إِلَّا قَلِيلٗا مِّمَّا تُحۡصِنُونَ","1644":"ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ عَامٞ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعۡصِرُونَ","1649":"وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦٓ أَسۡتَخۡلِصۡهُ لِنَفۡسِيۖ فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلۡيَوۡمَ لَدَيۡنَا مَكِينٌ أَمِينٞ","1650":"قَالَ ٱجۡعَلۡنِي عَلَىٰ خَزَآئِنِ ٱلۡأَرۡضِۖ إِنِّي حَفِيظٌ عَلِيمٞ","1717":"لَهُۥ مُعَقِّبَٰتٞ مِّنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ يَحۡفَظُونَهُۥ مِنۡ أَمۡرِ ٱللَّهِۗ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡۗ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوۡمٖ سُوٓءٗا فَلَا مَرَدَّ لَهُۥۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ","1820":"وَٱلۡأَرۡضَ مَدَدۡنَٰهَا وَأَلۡقَيۡنَا فِيهَا رَوَٰسِيَ وَأَنۢبَتۡنَا فِيهَا مِن كُلِّ شَيۡءٖ مَّوۡزُونٖ","1821":"وَجَعَلۡنَا لَكُمۡ فِيهَا مَعَٰيِشَ وَمَن لَّسۡتُمۡ لَهُۥ بِرَٰزِقِينَ","1997":"مَنۡ عَمِلَ صَٰلِحٗا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَلَنُحۡيِيَنَّهُۥ حَيَوٰةٗ طَيِّبَةٗۖ وَلَنَجۡزِيَنَّهُمۡ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ","2057":"وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ فَتَقۡعُدَ مَلُومٗا مَّحۡسُورًا","2063":"وَأَوۡفُواْ ٱلۡكَيۡلَ إِذَا كِلۡتُمۡ وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِۚ ذَٰلِكَ خَيۡرٞ وَأَحۡسَنُ تَأۡوِيلٗا","2169":"إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ إِنَّا لَا نُضِيعُ أَجۡرَ مَنۡ أَحۡسَنَ عَمَلًا","2216":"فَٱنطَلَقَا حَتَّىٰٓ إِذَآ أَتَيَآ أَهۡلَ قَرۡيَةٍ ٱسۡتَطۡعَمَآ أَهۡلَهَا فَأَبَوۡاْ أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارٗا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُۥۖ قَالَ لَوۡ شِئۡتَ لَتَّخَذۡتَ عَلَيۡهِ أَجۡرٗا","2218":"أَمَّا ٱلسَّفِينَةُ فَكَانَتۡ لِمَسَٰكِينَ يَعۡمَلُونَ فِي ٱلۡبَحۡرِ فَأَرَدتُّ أَنۡ أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكٞ يَأۡخُذُ كُلَّ سَفِينَةٍ غَصۡبٗا","2221":"وَأَمَّا ٱلۡجِدَارُ فَكَانَ لِغُلَٰمَيۡنِ يَتِيمَيۡنِ فِي ٱلۡمَدِينَةِ وَكَانَ تَحۡتَهُۥ كَنزٞ لَّهُمَا وَكَانَ أَبُوهُمَا صَٰلِحٗا فَأَرَادَ رَبُّكَ أَن يَبۡلُغَآ أَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَنزَهُمَا رَحۡمَةٗ مِّن رَّبِّكَۚ وَمَا فَعَلۡتُهُۥ عَنۡ أَمۡرِيۚ ذَٰلِكَ تَأۡوِيلُ مَا لَمۡ تَسۡطِع عَّلَيۡهِ صَبۡرٗا","2233":"قَالُواْ يَٰذَا ٱلۡقَرۡنَيۡنِ إِنَّ يَأۡجُوجَ وَمَأۡجُوجَ مُفۡسِدُونَ فِي ٱلۡأَرۡضِ فَهَلۡ نَجۡعَلُ لَكَ خَرۡجًا عَلَىٰٓ أَن تَجۡعَلَ بَيۡنَنَا وَبَيۡنَهُمۡ سَدّٗا","2234":"قَالَ مَا مَكَّنِّي فِيهِ رَبِّي خَيۡرٞ فَأَعِينُونِي بِقُوَّةٍ أَجۡعَلۡ بَيۡنَكُمۡ وَبَيۡنَهُمۡ رَدۡمًا","2235":"ءَاتُونِي زُبَرَ ٱلۡحَدِيدِۖ حَتَّىٰٓ إِذَا سَاوَىٰ بَيۡنَ ٱلصَّدَفَيۡنِ قَالَ ٱنفُخُواْۖ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارٗا قَالَ ءَاتُونِيٓ أُفۡرِغۡ عَلَيۡهِ قِطۡرٗا","2236":"فَمَا ٱسۡطَٰعُوٓاْ أَن يَظۡهَرُوهُ وَمَا ٱسۡتَطَٰعُواْ لَهُۥ نَقۡبٗا","2274":"وَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَٰقِطۡ عَلَيۡكِ رُطَبٗا جَنِيّٗا","2562":"وَعَلَّمۡنَٰهُ صَنۡعَةَ لَبُوسٖ لَّكُمۡ لِتُحۡصِنَكُم مِّنۢ بَأۡسِكُمۡۖ فَهَلۡ أَنتُمۡ شَٰكِرُونَ","2680":"وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ","2699":"فَأَوۡحَيۡنَآ إِلَيۡهِ أَنِ ٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا فَإِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ فَٱسۡلُكۡ فِيهَا مِن كُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ مِنۡهُمۡۖ وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ","2723":"يَٰٓأَيُّهَا ٱلرُّسُلُ كُلُواْ مِنَ ٱلطَّيِّبَٰتِ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ عَلِيمٞ","2827":"رِجَالٞ لَّا تُلۡهِيهِمۡ تِجَٰرَةٞ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ يَخَافُونَ يَوۡمٗا تَتَقَلَّبُ فِيهِ ٱلۡقُلُوبُ وَٱلۡأَبۡصَٰرُ","2921":"وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامٗا","3112":"۞ أَوۡفُواْ ٱلۡكَيۡلَ وَلَا تَكُونُواْ مِنَ ٱلۡمُخۡسِرِينَ","3113":"وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِ","3114":"وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ","3246":"وَتَرَى ٱلۡجِبَالَ تَحۡسَبُهَا جَامِدَةٗ وَهِيَ تَمُرُّ مَرَّ ٱلسَّحَابِۚ صُنۡعَ ٱللَّهِ ٱلَّذِيٓ أَتۡقَنَ كُلَّ شَيۡءٍۚ إِنَّهُۥ خَبِيرُۢ بِمَا تَفۡعَلُونَ","3274":"وَلَمَّا وَرَدَ مَآءَ مَدۡيَنَ وَجَدَ عَلَيۡهِ أُمَّةٗ مِّنَ ٱلنَّاسِ يَسۡقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمۡرَأَتَيۡنِ تَذُودَانِۖ قَالَ مَا خَطۡبُكُمَاۖ قَالَتَا لَا نَسۡقِي حَتَّىٰ يُصۡدِرَ ٱلرِّعَآءُۖ وَأَبُونَا شَيۡخٞ كَبِيرٞ","3275":"فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّي لِمَآ أَنزَلۡتَ إِلَيَّ مِنۡ خَيۡرٖ فَقِيرٞ","3276":"فَجَآءَتۡهُ إِحۡدَىٰهُمَا تَمۡشِي عَلَى ٱسۡتِحۡيَآءٖ قَالَتۡ إِنَّ أَبِي يَدۡعُوكَ لِيَجۡزِيَكَ أَجۡرَ مَا سَقَيۡتَ لَنَاۚ فَلَمَّا جَآءَهُۥ وَقَصَّ عَلَيۡهِ ٱلۡقَصَصَ قَالَ لَا تَخَفۡۖ نَجَوۡتَ مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ","3277":"قَالَتۡ إِحۡدَىٰهُمَا يَٰٓأَبَتِ ٱسۡتَـٔۡجِرۡهُۖ إِنَّ خَيۡرَ مَنِ ٱسۡتَـٔۡجَرۡتَ ٱلۡقَوِيُّ ٱلۡأَمِينُ","3278":"قَالَ إِنِّيٓ أُرِيدُ أَنۡ أُنكِحَكَ إِحۡدَى ٱبۡنَتَيَّ هَٰتَيۡنِ عَلَىٰٓ أَن تَأۡجُرَنِي ثَمَٰنِيَ حِجَجٖۖ فَإِنۡ أَتۡمَمۡتَ عَشۡرٗا فَمِنۡ عِندِكَۖ وَمَآ أُرِيدُ أَنۡ أَشُقَّ عَلَيۡكَۚ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰلِحِينَ","3279":"قَالَ ذَٰلِكَ بَيۡنِي وَبَيۡنَكَۖ أَيَّمَا ٱلۡأَجَلَيۡنِ قَضَيۡتُ فَلَا عُدۡوَٰنَ عَلَيَّۖ وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٞ","3327":"۞ إِنَّ قَٰرُونَ كَانَ مِن قَوۡمِ مُوسَىٰ فَبَغَىٰ عَلَيۡهِمۡۖ وَءَاتَيۡنَٰهُ مِنَ ٱلۡكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِٱلۡعُصۡبَةِ أُوْلِي ٱلۡقُوَّةِ إِذۡ قَالَ لَهُۥ قَوۡمُهُۥ لَا تَفۡرَحۡۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡفَرِحِينَ","3328":"وَٱبۡتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلۡأٓخِرَةَۖ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ وَأَحۡسِن كَمَآ أَحۡسَنَ ٱللَّهُ إِلَيۡكَۖ وَلَا تَبۡغِ ٱلۡفَسَادَ فِي ٱلۡأَرۡضِۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ","3329":"قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمٍ عِندِيٓۚ أَوَلَمۡ يَعۡلَمۡ أَنَّ ٱللَّهَ قَدۡ أَهۡلَكَ مِن قَبۡلِهِۦ مِنَ ٱلۡقُرُونِ مَنۡ هُوَ أَشَدُّ مِنۡهُ قُوَّةٗ وَأَكۡثَرُ جَمۡعٗاۚ وَلَا يُسۡـَٔلُ عَن ذُنُوبِهِمُ ٱلۡمُجۡرِمُونَ","3615":"۞ وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ مِنَّا فَضۡلٗاۖ يَٰجِبَالُ أَوِّبِي مَعَهُۥ وَٱلطَّيۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِيدَ","3616":"أَنِ ٱعۡمَلۡ سَٰبِغَٰتٖ وَقَدِّرۡ فِي ٱلسَّرۡدِۖ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ بَصِيرٞ","3617":"وَلِسُلَيۡمَٰنَ ٱلرِّيحَ غُدُوُّهَا شَهۡرٞ وَرَوَاحُهَا شَهۡرٞۖ وَأَسَلۡنَا لَهُۥ عَيۡنَ ٱلۡقِطۡرِۖ وَمِنَ ٱلۡجِنِّ مَن يَعۡمَلُ بَيۡنَ يَدَيۡهِ بِإِذۡنِ رَبِّهِۦۖ وَمَن يَزِغۡ مِنۡهُمۡ عَنۡ أَمۡرِنَا نُذِقۡهُ مِنۡ عَذَابِ ٱلسَّعِيرِ","3618":"يَعۡمَلُونَ لَهُۥ مَا يَشَآءُ مِن مَّحَٰرِيبَ وَتَمَٰثِيلَ وَجِفَانٖ كَٱلۡجَوَابِ وَقُدُورٖ رَّاسِيَٰتٍۚ ٱعۡمَلُوٓاْ ءَالَ دَاوُۥدَ شُكۡرٗاۚ وَقَلِيلٞ مِّنۡ عِبَادِيَ ٱلشَّكُورُ","4822":"وَأَن لَّيۡسَ لِلۡإِنسَٰنِ إِلَّا مَا سَعَىٰ","4823":"وَأَنَّ سَعۡيَهُۥ سَوۡفَ يُرَىٰ","4824":"ثُمَّ يُجۡزَىٰهُ ٱلۡجَزَآءَ ٱلۡأَوۡفَىٰ","4907":"وَٱلسَّمَآءَ رَفَعَهَا وَوَضَعَ ٱلۡمِيزَانَ","4908":"أَلَّا تَطۡغَوۡاْ فِي ٱلۡمِيزَانِ","4909":"وَأَقِيمُواْ ٱلۡوَزۡنَ بِٱلۡقِسۡطِ وَلَا تُخۡسِرُواْ ٱلۡمِيزَانَ","5185":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نُودِيَ لِلصَّلَوٰةِ مِن يَوۡمِ ٱلۡجُمُعَةِ فَٱسۡعَوۡاْ إِلَىٰ ذِكۡرِ ٱللَّهِ وَذَرُواْ ٱلۡبَيۡعَۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","5186":"فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ فِي ٱلۡأَرۡضِ وَٱبۡتَغُواْ مِن فَضۡلِ ٱللَّهِ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ","5196":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُلۡهِكُمۡ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ","5242":"ٱلَّذِي خَلَقَ ٱلۡمَوۡتَ وَٱلۡحَيَوٰةَ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡغَفُورُ","5255":"هُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ ذَلُولٗا فَٱمۡشُواْ فِي مَنَاكِبِهَا وَكُلُواْ مِن رِّزۡقِهِۦۖ وَإِلَيۡهِ ٱلنُّشُورُ","5494":"۞ إِنَّ رَبَّكَ يَعۡلَمُ أَنَّكَ تَقُومُ أَدۡنَىٰ مِن ثُلُثَيِ ٱلَّيۡلِ وَنِصۡفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٞ مِّنَ ٱلَّذِينَ مَعَكَۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيۡلَ وَٱلنَّهَارَۚ عَلِمَ أَن لَّن تُحۡصُوهُ فَتَابَ عَلَيۡكُمۡۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنَ ٱلۡقُرۡءَانِۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرۡضَىٰ وَءَاخَرُونَ يَضۡرِبُونَ فِي ٱلۡأَرۡضِ يَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ وَءَاخَرُونَ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنۡهُۚ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَقۡرِضُواْ ٱللَّهَ قَرۡضًا حَسَنٗاۚ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنۡ خَيۡرٖ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيۡرٗا وَأَعۡظَمَ أَجۡرٗاۚ وَٱسۡتَغۡفِرُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمُۢ","5848":"وَيۡلٞ لِّلۡمُطَفِّفِينَ","5849":"ٱلَّذِينَ إِذَا ٱكۡتَالُواْ عَلَى ٱلنَّاسِ يَسۡتَوۡفُونَ","5850":"وَإِذَا كَالُوهُمۡ أَو وَّزَنُوهُمۡ يُخۡسِرُونَ","5851":"أَلَا يَظُنُّ أُوْلَٰٓئِكَ أَنَّهُم مَّبۡعُوثُونَ","5852":"لِيَوۡمٍ عَظِيمٖ","5853":"يَوۡمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلۡعَٰلَمِينَ","6096":"فَإِذَا فَرَغۡتَ فَٱنصَبۡ","6097":"وَإِلَىٰ رَبِّكَ فَٱرۡغَب","6144":"فَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ","6145":"وَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٖ شَرّٗا يَرَهُۥ"},"nay":87,"nq":61};
